/// <summary>
/// PricingAttribute of table <c>CustTable</c> field DefaultDirectDebitMandate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableDefaultDirectDebitMandate extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, DefaultDirectDebitMandate);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Int64);
    CustTable   custTable;

    while select DefaultDirectDebitMandate from custTable
        group by DefaultDirectDebitMandate
    {
        ret.add(custTable.DefaultDirectDebitMandate);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, DefaultDirectDebitMandate));
    qbr.value(queryValue(_value));
}
